export function makeList(n) {
  const out = [];
  for (let i = 0; i < n; i++) out.push({ id: i, tag: "s" + i });
  return out;
}

export function makeMap() {
  return new Map([["alpha", 1], ["beta", 2]]);
}

export function* gen(n) {
  for (let i = 0; i < n; i++) yield i * 3;
}

export function register(entry) {
  return {
    describe() {
      return entry.label + ":" + JSON.stringify(entry.initConfig);
    },
    fallback: entry.defaultFallback({ kind: "seeded" }),
    bare: entry.defaultFallback(),
    load: entry.load,
    seed: entry.seed,
  };
}
